    /// The theme for an appearance.
    static func theme(dark: Bool) -> Theme {
        dark ? Self.dark : Self.light
    }

    /// What is in this file on the supervisor's say and not yet the user's.
    /// Each is one value in the data; ruling on it is one edit there.
    static let tentative: [String] = [
        "window_tab.working_glyph_shown",
        "side.fix_line_height",
        "side.ask_max_lines",
        "side.ask_max_steps",
        "stack_tab.inset",
        "stack_tab.min_width",
        "elsewhere.veil",
        "selection.spring_damping",
        "selection.glass_at_rest",
        "selection.refraction_shown",
        "selection.seen_after",
        "highlight.breath_low",
        "text_on.problem_text",
    ]
}

#if canImport(AppKit)
import AppKit

extension ControlRoomLook {
    /// The theme for what a view is being drawn in right now.
    static func theme(for appearance: NSAppearance) -> Theme {
        theme(dark: appearance.bestMatch(from: [.darkAqua, .aqua]) == .darkAqua)
    }
}
#endif
